ALTER TABLE student_exit_types ADD COLUMN constraints_json TEXT NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS student_exit_action_policy (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',action TEXT NOT NULL,roles_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),updated_by TEXT,updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,action));
CREATE TABLE IF NOT EXISTS student_exit_destinations (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',code TEXT NOT NULL,label TEXT NOT NULL,room_id TEXT,opening_hours_json TEXT NOT NULL DEFAULT '{}',capacity INTEGER,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),updated_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,code));
CREATE TABLE IF NOT EXISTS student_exit_student_rules (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',student_id TEXT NOT NULL,exit_type_code TEXT,rule_kind TEXT NOT NULL CHECK(rule_kind IN ('allow','restrict','accommodation')),rule_json TEXT NOT NULL DEFAULT '{}',reason_visibility TEXT NOT NULL DEFAULT 'restricted' CHECK(reason_visibility IN ('standard','restricted')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),updated_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_student_exit_rules_student ON student_exit_student_rules(app_id,student_id,active);
